  buildTask: {
    parameters: {
      query?: never;
      header?: {
        "Payment-Signature"?: string;
        "Idempotency-Key"?: string;
      };
      path?: never;
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json":
          | {
              intent: string;
              /** @enum {integer} */
              chainId: 5042 | 5042002;
              sender: string;
              payer?: string;
              constraints?: {
                /** @description Maximum gross outgoing native USDC in 18-decimal base units, represented as an integer string. */
                maxOutgoingUsdcWei?: string;
                /**
                 * Format: uint64
                 * @description Maximum simulated gas units across all actions.
                 */
                maxGasUnits?: number;
                /**
                 * @description If nonempty, every action target must be in this allowlist.
                 * @default []
                 */
                allowedTargets?: string[];
                /** @default [] */
                minimumReceived?: {
                  /** @description Currently supported: native (18-decimal USDC units) or Arc USDC precompile 0x3600000000000000000000000000000000000000 (6-decimal units). Other assets fail closed because received-balance evidence is unavailable. */
                  asset: string;
                  /** @description Minimum net increase in the sender balance across the simulated batch, in the specified asset's base units. */
                  amount: string;
                }[];
              };
              /** @description Required in body or Idempotency-Key header. */
              idempotencyKey?: string;
            }
          | {
              /** Format: uuid */
              quoteId: string;
              retrievalToken: string;
            };
      };
    };
    responses: {
      /** @description Exact frozen JSON artifact bytes (build, report, safe summary and pricing), released only after payment acceptance. Payment-Response is returned when available; accepted is distinct from batch settlement. */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Payment submitted or ambiguous; retry the same quote/token for recovery. Artifact remains private. */
      202: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      401: components["responses"]["Error"];
      /** @description Safe summary, pricing, quoteId, expiresAt, SHA-256 payloadHash, EdDSA attestation, retrievalToken and base64 Gateway paymentRequired. No build/calldata/full report. */
      402: {
        headers: {
          "Payment-Required"?: string;
          [name: string]: unknown;
        };
        content?: never;
      };
      403: components["responses"]["Error"];
      /** @description Request key conflict, active preparation, or incompatible payment replay. */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      default: components["responses"]["Error"];
    };
  };
